        // 撤销证书：立即失去当前可用资格
        mvc.perform(post("/api/certificates/{id}/revoke", certId)).andExpect(status().isOk());
        mvc.perform(get("/api/measurements/usable")).andExpect(jsonPath("$.length()").value(0));

        // 原始测量、计算值与放行历史保留，状态仍为 RELEASED，不回写为从未放行
