                .andExpect(jsonPath("$.status").value("PENDING"));
    }

    @Test
    void batchSizeAndActorValidation() throws Exception {
        createCert("INS-1", "1", "0");
        submit("R-1", "INS-1", "1", "0", "9", "alice");

